	if s == nil {
		return [12]byte{}, dmrgo.ErrNilReceiver
	}

	var data [12]byte
	if s.LastBlock {
		data[0] |= 0x80
	}
	if s.ProtectFlag {
		data[0] |= 0x40
	}
	if uint64(s.Opcode)>>6 != 0 {
		return [12]byte{}, errCSBKOpcodeRange
	}
	data[0] = data[0]&^0x3F | byte(uint64(s.Opcode))&0x3F
